WITH lp2_passage_6 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Confirming a Hotel Reservation', 'Good afternoon. I am calling to confirm a reservation for two nights, from March 12th to March 14th. The booking is under the name Patterson, first name Linda. I also requested a room with a view of the garden. Could you check that, please? Yes, Ms. Patterson, I can see your booking here. You have a garden-view room on the fourth floor. Breakfast is included and starts at seven a.m. Perfect, thank you very much.', 'listening', 'A2', 'call')
  RETURNING id
)
