WITH lp2_passage_12 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Following Up on a Proposal', 'Hi James, this is Nadia from Apex Solutions. I''m calling to follow up on the proposal we sent you last Tuesday. I wanted to make sure you received it and to see if you had any questions. We included two pricing options, as you requested. The first one covers the basic package with standard support, and the second includes premium support with a dedicated account manager. Our team is available for a call this week if you''d like to discuss the details. Please let me know what works best for your schedule.', 'listening', 'B1', 'email')
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B1', 'mcq', 'email', 'When was the proposal sent?', to_jsonb(ARRAY['Last Monday','Last Tuesday','Last Wednesday','Last Friday']::text[]), 'Last Tuesday', 'Nadia says ''the proposal we sent you last Tuesday.'' The other days are not mentioned in the message.', (SELECT id FROM lp2_passage_12)),
  ('listening', 'B1', 'mcq', 'email', 'What is included in the second pricing option that the first does not have?', to_jsonb(ARRAY['Free shipping','A longer contract','Premium support with a dedicated account manager','A money-back guarantee']::text[]), 'Premium support with a dedicated account manager', 'Nadia explains that ''the second includes premium support with a dedicated account manager,'' while the first only covers ''standard support.'' The other options are not part of either package.', (SELECT id FROM lp2_passage_12)),
  ('listening', 'B1', 'mcq', 'email', 'What does Nadia suggest as a next step?', to_jsonb(ARRAY['Signing the contract immediately','Visiting their office','Scheduling a call this week','Sending a revised proposal']::text[]), 'Scheduling a call this week', 'Nadia says ''our team is available for a call this week if you''d like to discuss the details.'' She does not suggest signing, visiting, or revising at this stage.', (SELECT id FROM lp2_passage_12));

WITH lp2_passage_13 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Contract Renewal Terms', 'Thank you for meeting with me today to discuss the renewal. We''ve been happy with your services over the past two years, but we do have a few concerns. First, the response time for support tickets has increased from four hours to over twelve hours in the last quarter. Second, we''d like to negotiate a lower rate, since we''re committing to a three-year term instead of two. If you can address the support issue and offer a five percent reduction, we''re ready to sign by the end of the month.', 'listening', 'B1', 'negotiation')
  RETURNING id
)
