  ('listening', 'B1', 'mcq', 'negotiation', 'How long has the current contract been in place?', to_jsonb(ARRAY['One year','Two years','Three years','Five years']::text[]), 'Two years', 'The speaker says ''we''ve been happy with your services over the past two years.'' Three years refers to the proposed new term, not the current contract length.', (SELECT id FROM lp2_passage_13)),
  ('listening', 'B1', 'mcq', 'negotiation', 'What is the main concern about support?', to_jsonb(ARRAY['The support team is too small','The response time has increased','The support is only available by email','The support contract expired']::text[]), 'The response time has increased', 'The speaker says ''the response time for support tickets has increased from four hours to over twelve hours.'' The other issues are not raised.', (SELECT id FROM lp2_passage_13)),
  ('listening', 'B1', 'mcq', 'negotiation', 'What two conditions must be met before signing?', to_jsonb(ARRAY['Faster delivery and a free trial','A new account manager and longer hours','Fixing the support issue and a five percent reduction','Adding more features and removing the cancellation fee']::text[]), 'Fixing the support issue and a five percent reduction', 'The speaker says ''if you can address the support issue and offer a five percent reduction, we''re ready to sign.'' The other pairs of conditions are not mentioned.', (SELECT id FROM lp2_passage_13));

WITH lp2_passage_14 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('New Security Badge Policy', 'Good afternoon, everyone. Starting September first, we are introducing a new security badge policy for all employees. You will need to tap your badge at every entrance, including internal doors between departments. The old badges will stop working on August thirty-first, so please visit the security office on the ground floor before that date to pick up your new badge. You will need to bring a valid photo ID. If you work remotely and only come to the office occasionally, you can request your badge by email and collect it on your next visit. Any questions can be directed to the security team at extension 4500.', 'listening', 'B1', 'general')
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B1', 'mcq', 'general', 'When will the old badges stop working?', to_jsonb(ARRAY['September first','September thirtieth','August thirty-first','August fifteenth']::text[]), 'August thirty-first', 'The speaker says ''the old badges will stop working on August thirty-first.'' September first is when the new policy starts, not when old badges expire.', (SELECT id FROM lp2_passage_14)),
  ('listening', 'B1', 'mcq', 'general', 'What must employees bring to get a new badge?', to_jsonb(ARRAY['Their old badge','A valid photo ID','A signed form from their manager','Two passport photos']::text[]), 'A valid photo ID', 'The speaker says ''you will need to bring a valid photo ID.'' The other items are not required according to the announcement.', (SELECT id FROM lp2_passage_14)),
  ('listening', 'B1', 'mcq', 'general', 'How can remote employees request their new badge?', to_jsonb(ARRAY['By calling extension 4500','By visiting the ground floor','By email','By asking their manager']::text[]), 'By email', 'The speaker says remote employees ''can request your badge by email and collect it on your next visit.'' Extension 4500 is for questions, not badge requests.', (SELECT id FROM lp2_passage_14));

WITH lp2_passage_15 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Reporting a Software Bug', 'Hi, this is Clara from the accounting department. I''m calling because we''ve found a bug in the new invoicing software that was installed last week. When we try to generate a report for dates before January first, the system crashes and displays an error code, E-4012. It has happened to three different users on our team, so it''s not just my computer. We need this fixed as soon as possible because our quarterly audit starts next Monday and we need access to last year''s data. Could someone from your team look into it today?', 'listening', 'B1', 'call')
  RETURNING id
)
