  ('listening', 'B1', 'mcq', 'call', 'Why does Clara say it is not just her computer?', to_jsonb(ARRAY['She tested it on a different network','Her manager confirmed the issue','Three different users experienced the same problem','The IT team already investigated']::text[]), 'Three different users experienced the same problem', 'Clara says ''it has happened to three different users on our team, so it''s not just my computer.'' This rules out a single-machine issue. The other explanations are not given.', (SELECT id FROM lp2_passage_15)),
  ('listening', 'B1', 'mcq', 'call', 'Why is the fix urgent?', to_jsonb(ARRAY['A client presentation is tomorrow','The software licence expires soon','The quarterly audit starts next Monday','The CEO requested a report']::text[]), 'The quarterly audit starts next Monday', 'Clara says ''our quarterly audit starts next Monday and we need access to last year''s data.'' The other reasons are not mentioned.', (SELECT id FROM lp2_passage_15));

WITH lp2_passage_16 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Quarterly Performance Review', 'Alright, let''s go over the key points from this quarter. Overall, the team met eighty-five percent of its targets, which is an improvement over last quarter''s seventy-eight percent. Customer satisfaction scores went up by three points, mainly because we reduced average response time from forty-eight hours to thirty-six hours. On the other hand, the onboarding process for new clients still takes too long. Right now it averages fourteen days, and our goal is to bring it down to ten. I''d like each team lead to propose one improvement by next Wednesday.', 'listening', 'B1', 'meeting')
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B1', 'mcq', 'meeting', 'What percentage of targets did the team meet this quarter?', to_jsonb(ARRAY['Seventy-eight percent','Eighty percent','Eighty-five percent','Ninety percent']::text[]), 'Eighty-five percent', 'The speaker says ''the team met eighty-five percent of its targets.'' Seventy-eight percent was last quarter''s result, not the current one.', (SELECT id FROM lp2_passage_16)),
  ('listening', 'B1', 'mcq', 'meeting', 'Why did customer satisfaction scores improve?', to_jsonb(ARRAY['New products were launched','Prices were reduced','Average response time decreased','More staff were hired']::text[]), 'Average response time decreased', 'The speaker says scores went up ''mainly because we reduced average response time from forty-eight hours to thirty-six hours.'' The other reasons are not given.', (SELECT id FROM lp2_passage_16)),
  ('listening', 'B1', 'mcq', 'meeting', 'What is the goal for the client onboarding process?', to_jsonb(ARRAY['Seven days','Ten days','Twelve days','Fourteen days']::text[]), 'Ten days', 'The speaker says ''our goal is to bring it down to ten.'' Fourteen days is the current average, not the target. The other durations are not mentioned.', (SELECT id FROM lp2_passage_16));

WITH lp2_passage_17 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES ('Handling a Billing Dispute', 'Thank you for calling. I understand your concern, Mr. Tremblay. Let me pull up your account. I can see that you were charged twice for the same service in June, once on June third and again on June seventeenth. The second charge of two hundred and forty dollars was a system error on our end. I sincerely apologise for the inconvenience. I will process a refund right away, and it should appear on your statement within five to seven business days. I will also send you a confirmation email with a reference number so you have it for your records. Is there anything else I can help you with today?', 'listening', 'B1', 'customer_service')
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B1', 'mcq', 'customer_service', 'What was the billing problem?', to_jsonb(ARRAY['The customer was undercharged','The customer was charged for the wrong service','The customer was charged twice for the same service','The customer''s payment was declined']::text[]), 'The customer was charged twice for the same service', 'The agent says ''you were charged twice for the same service in June.'' The other billing issues are not described.', (SELECT id FROM lp2_passage_17)),
  ('listening', 'B1', 'mcq', 'customer_service', 'How much was the incorrect charge?', to_jsonb(ARRAY['One hundred and twenty dollars','Two hundred dollars','Two hundred and forty dollars','Three hundred dollars']::text[]), 'Two hundred and forty dollars', 'The agent says ''the second charge of two hundred and forty dollars was a system error.'' The other amounts are not mentioned.', (SELECT id FROM lp2_passage_17)),
  ('listening', 'B1', 'mcq', 'customer_service', 'How long will the refund take to appear?', to_jsonb(ARRAY['One to two business days','Three to five business days','Five to seven business days','Ten to fourteen business days']::text[]), 'Five to seven business days', 'The agent says ''it should appear on your statement within five to seven business days.'' The other timeframes are not stated.', (SELECT id FROM lp2_passage_17));
-- Listening passages round 2: 18 passages (6 B2, 6 C1, 6 C2) with 3 MCQs each

-- ============================================================
-- B2 PASSAGES (lp2_passage_18 through lp2_passage_23)
-- ============================================================

-- B2 #1: Budget Discussion (meeting)
WITH lp2_passage_18 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Quarterly Budget Review',
      'Good morning, everyone. I''d like to go over the Q3 budget figures before we finalize anything. As you can see from the spreadsheet, our marketing spend came in twelve percent over the original projection. Sarah mentioned during our last call that the digital campaign required additional funding because the initial results were so promising. However, the operations team has flagged that their equipment maintenance budget is running dangerously low. David suggested that we reallocate some of the unused travel budget to cover the shortfall, since most client meetings have moved online anyway. I''m inclined to agree, but I want to hear from finance first. If we approve the reallocation, we would still need sign-off from the regional director. She told me yesterday that she would be open to it as long as we provide a detailed justification. So, what I need from each department head by Friday is a revised forecast for Q4 that reflects these changes. Let''s not repeat the situation we had last year where we scrambled to find funds in December.',
      'listening', 'B2', 'meeting'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'meeting', 'Why did the marketing budget exceed its original projection?', to_jsonb(ARRAY['The marketing team made errors in their initial calculations','The digital campaign needed more investment due to strong early performance','The operations team borrowed from the marketing budget','The regional director approved additional spending']::text[]), 'The digital campaign needed more investment due to strong early performance', 'The speaker states that "the digital campaign required additional funding because the initial results were so promising." This directly explains the overspend. The passage does not mention calculation errors, operations borrowing from marketing, or the regional director approving extra spending.', (SELECT id FROM lp2_passage_18)),
  ('listening', 'B2', 'mcq', 'meeting', 'What can you infer about the company''s travel patterns compared to the previous year?', to_jsonb(ARRAY['Employees are traveling more frequently than before','Business travel has decreased significantly','The travel budget was increased for Q3','Travel expenses exceeded expectations']::text[]), 'Business travel has decreased significantly', 'The speaker says David suggested reallocating "the unused travel budget" because "most client meetings have moved online anyway." The word "unused" combined with the shift to online meetings implies a significant decrease in business travel. There is no indication of increased travel, a larger travel budget, or travel expenses exceeding expectations.', (SELECT id FROM lp2_passage_18)),
  ('listening', 'B2', 'mcq', 'meeting', 'What does the speaker require from department heads?', to_jsonb(ARRAY['A detailed justification for the regional director','An updated Q4 forecast reflecting the proposed changes','A list of all unused budget items across departments','Approval of the marketing overspend']::text[]), 'An updated Q4 forecast reflecting the proposed changes', 'The speaker explicitly says, "what I need from each department head by Friday is a revised forecast for Q4 that reflects these changes." The detailed justification is needed for the regional director but is not what the speaker is requesting from all department heads. The other options are not mentioned as requirements.', (SELECT id FROM lp2_passage_18));

-- B2 #2: Customer Complaint Call (call)
WITH lp2_passage_19 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Handling a Shipping Delay',
      'Thank you for calling Meridian Logistics, my name is Karen. How can I help you today? Yes, I understand your frustration, Mr. Tanaka. I can see from our system that your shipment was due to arrive on Tuesday and it still hasn''t been delivered. Let me look into this for you right away. It appears that the consignment was held at our distribution centre in Rotterdam due to a documentation error. I do apologize for that. What I can do is escalate this to our priority handling team, which would mean your goods should arrive within forty-eight hours. Alternatively, if you need the items sooner, we could arrange an express courier from Rotterdam, but there would be an additional charge of approximately two hundred euros. I should mention that because the delay was caused by our error, we are prepared to offer you a fifteen percent discount on your next shipment as a gesture of goodwill. Would you like me to go ahead with the priority handling, or would you prefer the express option?',
      'listening', 'B2', 'call'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'call', 'What caused the delay in Mr. Tanaka''s shipment?', to_jsonb(ARRAY['A strike at the Rotterdam port','Incorrect paperwork at the distribution centre','Severe weather conditions during transit','The shipment was sent to the wrong address']::text[]), 'Incorrect paperwork at the distribution centre', 'Karen states that "the consignment was held at our distribution centre in Rotterdam due to a documentation error." This means incorrect paperwork caused the delay. There is no mention of strikes, weather conditions, or a wrong delivery address.', (SELECT id FROM lp2_passage_19)),
  ('listening', 'B2', 'mcq', 'call', 'Why might the speaker have mentioned the fifteen percent discount before asking for a decision?', to_jsonb(ARRAY['To distract the customer from the additional courier charge','To encourage the customer to accept the slower priority handling option','To soften the customer''s frustration and maintain the business relationship','To meet a company requirement for complaint resolution']::text[]), 'To soften the customer''s frustration and maintain the business relationship', 'By mentioning the discount as "a gesture of goodwill" before asking the customer to choose, Karen is strategically attempting to reduce the customer''s frustration and preserve the relationship. While it might indirectly encourage accepting priority handling, the primary purpose is relationship management, not manipulation. There is no evidence of a company requirement or an attempt to distract.', (SELECT id FROM lp2_passage_19)),
  ('listening', 'B2', 'mcq', 'call', 'What is the difference between the two options Karen offers?', to_jsonb(ARRAY['Priority handling is free but slower; express delivery costs extra but is faster','Both options are free but have different delivery timelines','Priority handling requires manager approval; express delivery does not','Express delivery includes insurance; priority handling does not']::text[]), 'Priority handling is free but slower; express delivery costs extra but is faster', 'Karen explains that priority handling would deliver within forty-eight hours at no additional cost, while the express courier option would arrive sooner but carries "an additional charge of approximately two hundred euros." The other options are not mentioned in the passage.', (SELECT id FROM lp2_passage_19));

-- B2 #3: Performance Review (general)
WITH lp2_passage_20 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Annual Performance Discussion',
      'So, James, as we wrap up your annual review, I want to highlight a few key areas. First, your project management skills have improved considerably since last year. The way you handled the Henderson account was particularly impressive. Your client reported that you kept them informed at every stage, which is exactly the kind of communication we value. On the other hand, I have noticed that your written reports could use some refinement. They contain all the necessary information, but the structure can be difficult to follow at times. I''d recommend our advanced business writing workshop, which runs every quarter. Another point worth discussing is your teamwork. Several colleagues mentioned that you tend to take on too much yourself rather than delegating. While your dedication is admirable, it can slow down the team''s overall output. For the coming year, I''d like you to focus on delegation and report writing. If you show strong progress in those areas, we can discuss a move to the senior associate position in your mid-year review.',
      'listening', 'B2', 'general'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'general', 'What was particularly noted about James''s handling of the Henderson account?', to_jsonb(ARRAY['He completed the project ahead of schedule','He kept the client well informed throughout the process','He negotiated a better contract price','He resolved a major conflict with the client']::text[]), 'He kept the client well informed throughout the process', 'The manager states that "your client reported that you kept them informed at every stage, which is exactly the kind of communication we value." There is no mention of early completion, pricing negotiations, or conflict resolution regarding the Henderson account.', (SELECT id FROM lp2_passage_20)),
  ('listening', 'B2', 'mcq', 'general', 'What can you infer about James''s personality from the feedback about teamwork?', to_jsonb(ARRAY['He is lazy and avoids responsibility','He is hardworking but struggles to trust others with tasks','He prefers working in large teams','He has frequent conflicts with colleagues']::text[]), 'He is hardworking but struggles to trust others with tasks', 'The manager says James tends "to take on too much yourself rather than delegating" and calls his dedication "admirable." This suggests he is hardworking but reluctant to hand off work to others, implying difficulty trusting colleagues with tasks. The passage explicitly praises his dedication, ruling out laziness, and mentions no conflicts.', (SELECT id FROM lp2_passage_20)),
  ('listening', 'B2', 'mcq', 'general', 'What condition must James meet to be considered for promotion?', to_jsonb(ARRAY['He must complete the advanced business writing workshop','He must show significant improvement in delegation and report writing','He must successfully manage three new client accounts','He must receive positive feedback from all team members']::text[]), 'He must show significant improvement in delegation and report writing', 'The manager says, "If you show strong progress in those areas, we can discuss a move to the senior associate position," referring to delegation and report writing. While the workshop is recommended, attending it alone is not stated as the condition. New client accounts and universal positive feedback are not mentioned.', (SELECT id FROM lp2_passage_20));

-- B2 #4: Email Follow-Up (email)
WITH lp2_passage_21 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Following Up on a Proposal',
      'Hi, this is a voicemail for Patricia Duval. Patricia, it''s Michael Chen from Apex Solutions. I''m calling to follow up on the proposal we sent over last Wednesday. I wanted to check whether you''ve had a chance to review it with your team. I know it was quite a detailed document, so please don''t feel rushed. However, I should let you know that the pricing we quoted is only valid until the end of the month, because our supplier costs are increasing in November. If you have any questions about the technical specifications, our lead engineer, Tom, would be happy to arrange a call with your IT department. Also, I noticed that the proposal didn''t include the optional maintenance package we discussed during our meeting. I''ve asked my assistant to send that as a separate attachment by email this afternoon. If the overall figures work for you, we could set up a meeting next week to go over the implementation timeline. You can reach me on this number or by email at m.chen@apexsolutions.com. I look forward to hearing from you.',
      'listening', 'B2', 'email'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'email', 'Why does Michael mention the end of the month?', to_jsonb(ARRAY['The project must start before November','The quoted prices will increase after that date','Patricia''s contract with another provider expires then','The supplier is changing at the end of the month']::text[]), 'The quoted prices will increase after that date', 'Michael says "the pricing we quoted is only valid until the end of the month, because our supplier costs are increasing in November." This clearly indicates the prices will go up after the month ends. He does not say the project must start by then, mention Patricia''s other contracts, or say the supplier is changing entirely.', (SELECT id FROM lp2_passage_21)),
  ('listening', 'B2', 'mcq', 'email', 'What was missing from the original proposal?', to_jsonb(ARRAY['The technical specifications for the IT department','The implementation timeline','The optional maintenance package','The contact details for the lead engineer']::text[]), 'The optional maintenance package', 'Michael says, "I noticed that the proposal didn''t include the optional maintenance package we discussed during our meeting." He then explains that his assistant will send it separately. The technical specifications are apparently in the proposal, the implementation timeline is for a future meeting, and Tom''s availability is offered but was not something missing.', (SELECT id FROM lp2_passage_21)),
  ('listening', 'B2', 'mcq', 'email', 'What can you infer about Michael''s communication style?', to_jsonb(ARRAY['He is aggressive and pushes for an immediate decision','He is patient but creates a sense of urgency with factual deadlines','He is indifferent about whether Patricia accepts the proposal','He relies entirely on email and avoids phone calls']::text[]), 'He is patient but creates a sense of urgency with factual deadlines', 'Michael says "please don''t feel rushed" showing patience, but then mentions the pricing deadline and supplier cost increase, creating factual urgency without being pushy. He offers multiple contact methods (phone and email), so he does not avoid calls. His tone is proactive, not indifferent, and he is clearly not aggressive.', (SELECT id FROM lp2_passage_21));

-- B2 #5: Negotiating Office Space (negotiation)
WITH lp2_passage_22 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Negotiating the Office Lease',
      'Thank you for meeting with us today, Ms. Okoro. We''ve reviewed the lease terms you sent, and overall we''re quite interested in the space. The location is ideal for our team, and the layout suits our needs well. However, we do have some concerns about the proposed rental rate. Given current market conditions, comparable spaces in this district are averaging about ten percent less per square metre. We''d like to propose a rate that reflects that. Additionally, we noticed the lease requires a three-year commitment with no break clause. That''s a significant commitment for a growing company like ours. Would you consider adding a break clause at the eighteen-month mark? In return, we''d be willing to commit to a longer notice period of six months rather than the standard three. We also wanted to ask about the fit-out costs. Your proposal states that the tenant covers all modifications, but given the amount of work the space needs, we feel it would be reasonable to split those costs. If we can reach an agreement on these three points, we''re ready to move forward quickly.',
      'listening', 'B2', 'negotiation'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'negotiation', 'How many points of negotiation does the speaker raise?', to_jsonb(ARRAY['Two: the rental rate and the lease duration','Three: the rental rate, the break clause, and the fit-out costs','Four: the location, the layout, the rate, and the lease terms','One: the overall cost of the lease']::text[]), 'Three: the rental rate, the break clause, and the fit-out costs', 'The speaker explicitly says "if we can reach an agreement on these three points" after discussing the rental rate, the break clause, and the fit-out costs. The location and layout are mentioned positively and are not points of negotiation. The speaker does not reduce everything to a single cost concern.', (SELECT id FROM lp2_passage_22)),
  ('listening', 'B2', 'mcq', 'negotiation', 'What does the speaker offer in exchange for a break clause?', to_jsonb(ARRAY['A higher rental rate per square metre','A longer notice period of six months','Payment of all fit-out costs upfront','A commitment to a five-year lease instead']::text[]), 'A longer notice period of six months', 'The speaker says, "Would you consider adding a break clause at the eighteen-month mark? In return, we''d be willing to commit to a longer notice period of six months rather than the standard three." This is a clear concession offered in exchange. The other options are not proposed as trade-offs for the break clause.', (SELECT id FROM lp2_passage_22)),
  ('listening', 'B2', 'mcq', 'negotiation', 'Why might the speaker have mentioned comparable market rates?', to_jsonb(ARRAY['To show that they have already found a better alternative','To strengthen their position by providing objective evidence for a lower rate','To threaten to leave if the rate is not reduced','To demonstrate their expertise in commercial real estate']::text[]), 'To strengthen their position by providing objective evidence for a lower rate', 'By citing that "comparable spaces in this district are averaging about ten percent less per square metre," the speaker uses market data as objective leverage for negotiating a lower rate. There is no threat to leave, no mention of a specific alternative, and the goal is negotiation, not demonstrating real estate expertise.', (SELECT id FROM lp2_passage_22));

-- B2 #6: Onboarding New Software (customer_service)
WITH lp2_passage_23 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Software Onboarding Support Call',
      'Good afternoon, this is the Cloudworks support team. Thank you for contacting us about your onboarding experience. I can see from your account that your company activated the enterprise licence last week. You mentioned that your team is having trouble with the data migration feature. That''s actually one of the most common issues new clients face during setup. The problem usually occurs when the source database uses a date format that differs from our system''s default. I''d recommend checking your export settings first. If the dates are in day-month-year format, you''ll need to select the European standard option in our import wizard. I can also schedule a screen-sharing session with one of our onboarding specialists if you''d prefer guided assistance. Those sessions typically last about forty-five minutes and are included in your enterprise package at no extra cost. In the meantime, I''ll send you a link to our step-by-step migration guide, which covers the most common formatting issues. Most clients have the migration completed within two business days after following those steps.',
      'listening', 'B2', 'customer_service'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'B2', 'mcq', 'customer_service', 'What is the most likely cause of the data migration problem?', to_jsonb(ARRAY['The enterprise licence has not been fully activated','The source database uses a different date format than the system expects','The company''s internet connection is too slow for large data transfers','The migration feature is not included in the enterprise package']::text[]), 'The source database uses a different date format than the system expects', 'The support agent explains that "the problem usually occurs when the source database uses a date format that differs from our system''s default." The licence is already active, internet speed is not mentioned, and the migration feature is clearly part of the package since they are troubleshooting it.', (SELECT id FROM lp2_passage_23)),
  ('listening', 'B2', 'mcq', 'customer_service', 'What can you infer about the frequency of this issue?', to_jsonb(ARRAY['It is extremely rare and requires developer intervention','It is a known and common issue during initial setup','It only affects clients using the European date format','It was recently introduced by a software update']::text[]), 'It is a known and common issue during initial setup', 'The agent says "that''s actually one of the most common issues new clients face during setup" and also mentions a pre-existing step-by-step migration guide. This indicates the issue is well known and frequently encountered. It is not described as rare, exclusive to European formats, or caused by a recent update.', (SELECT id FROM lp2_passage_23)),
  ('listening', 'B2', 'mcq', 'customer_service', 'What does the support agent offer at no additional charge?', to_jsonb(ARRAY['A refund on the first month''s licence fee','A guided screen-sharing session with an onboarding specialist','An upgraded licence with additional features','A dedicated support agent for the first ninety days']::text[]), 'A guided screen-sharing session with an onboarding specialist', 'The agent says, "I can also schedule a screen-sharing session with one of our onboarding specialists" and clarifies these are "included in your enterprise package at no extra cost." Refunds, upgrades, and dedicated agents are not offered in the passage.', (SELECT id FROM lp2_passage_23));

-- ============================================================
-- C1 PASSAGES (lp2_passage_24 through lp2_passage_29)
-- ============================================================

-- C1 #1: Strategic Market Expansion (meeting)
WITH lp2_passage_24 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Evaluating the Southeast Asian Market',
      'Before we adjourn, I think we need to address the elephant in the room regarding our Southeast Asian expansion. The preliminary market research looks favourable on paper, but I have to be candid: I''m not entirely convinced we''ve done enough due diligence on the regulatory landscape. Vietnam and Thailand have been highlighted as our top two targets, and while the consumer demand is certainly there, the compliance requirements differ quite substantially between the two markets. Our legal team has flagged that Vietnam''s new data localization laws could require us to establish a local server infrastructure, which would add roughly four hundred thousand to our first-year costs. Thailand, on the other hand, has a more mature regulatory framework, but our competitor, Nexion, already holds about thirty-five percent of the market share there. I would argue that entering a market where we''d be playing catch-up from day one is a strategic risk we should weigh very carefully. What concerns me more, however, is the timeline. The board expects us to have boots on the ground by Q2, and frankly, I don''t see how we can do proper due diligence, hire a local team, and secure the necessary licences in that timeframe without cutting corners. I''d rather push the launch back by a quarter and do it right than rush in and damage our brand in a region where first impressions matter enormously.',
      'listening', 'C1', 'meeting'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'meeting', 'What does the speaker imply by saying they want to "address the elephant in the room"?', to_jsonb(ARRAY['The topic has been openly and thoroughly discussed already','There is an obvious problem that people have been avoiding','The expansion plan has been officially cancelled','A major competitor has raised objections to the plan']::text[]), 'There is an obvious problem that people have been avoiding', 'The idiom "the elephant in the room" refers to an important issue that everyone is aware of but no one has been willing to discuss openly. The speaker then proceeds to raise concerns about due diligence and regulatory issues, confirming this meaning. It does not imply the topic has been discussed, that the plan is cancelled, or that a competitor has objected.', (SELECT id FROM lp2_passage_24)),
  ('listening', 'C1', 'mcq', 'meeting', 'What is the speaker''s implicit recommendation regarding the two target markets?', to_jsonb(ARRAY['Vietnam is preferable despite higher initial costs','Thailand should be prioritized because of its mature regulations','Neither market should be entered under the current timeline','Both markets should be entered simultaneously to maximize impact']::text[]), 'Neither market should be entered under the current timeline', 'The speaker raises significant obstacles for both markets: Vietnam''s high data localization costs and Thailand''s entrenched competitor. More critically, the speaker says the board''s Q2 timeline is unrealistic and recommends pushing back by a quarter. The overall implication is that entering either market under the current conditions and timeline would be premature. The speaker does not explicitly favour one market over the other.', (SELECT id FROM lp2_passage_24)),
  ('listening', 'C1', 'mcq', 'meeting', 'Why does the speaker consider the Q2 timeline problematic?', to_jsonb(ARRAY['The budget has not yet been approved for the expansion','Completing due diligence, hiring, and licensing properly within that timeframe seems unfeasible','The competitor in Thailand has announced a major product launch in Q2','The legal team has recommended waiting until new regulations take effect']::text[]), 'Completing due diligence, hiring, and licensing properly within that timeframe seems unfeasible', 'The speaker explicitly says, "I don''t see how we can do proper due diligence, hire a local team, and secure the necessary licences in that timeframe without cutting corners." The concern is about the feasibility of completing essential preparatory steps. Budget approval, competitor launches, and waiting for new regulations are not mentioned as reasons.', (SELECT id FROM lp2_passage_24));

-- C1 #2: Crisis Communication (call)
WITH lp2_passage_25 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Managing a Data Breach Response',
      'Alright, thank you all for joining this emergency call. As you know, our security team detected unauthorized access to one of our customer databases at approximately two a.m. this morning. At this stage, we believe the breach affected records from our European operations, potentially impacting up to sixty thousand customers. I want to stress that this is a preliminary estimate and the forensic analysis is still ongoing. Now, our obligations under GDPR are clear: we have seventy-two hours from the moment of detection to notify the relevant supervisory authority. That gives us until Friday morning. However, I would strongly advise that we aim to have our notification ready by tomorrow evening to allow time for legal review. The communications team has drafted a customer notification template, but I have reservations about the tone. It reads too much like a legal disclaimer and not enough like a genuine acknowledgement of the situation. Our customers need to feel that we are taking this seriously, not that we are covering ourselves. I''ve asked Rebecca to revise it with input from our customer experience team. On the technical side, the vulnerability has been patched, but we are conducting a full audit of all access points, which should be completed within forty-eight hours. In the meantime, I need each department head to compile a list of any third-party vendors who had access to the affected systems.',
      'listening', 'C1', 'call'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'call', 'What does the speaker imply about the communications team''s initial draft?', to_jsonb(ARRAY['It contained factual errors about the breach','It prioritized legal protection over genuine customer empathy','It was too informal and lacked necessary legal disclaimers','It failed to mention the GDPR notification requirements']::text[]), 'It prioritized legal protection over genuine customer empathy', 'The speaker says the draft "reads too much like a legal disclaimer and not enough like a genuine acknowledgement of the situation," adding that "customers need to feel that we are taking this seriously, not that we are covering ourselves." This implies the tone was overly defensive and legalistic rather than empathetic. The speaker does not mention factual errors, excessive informality, or missing GDPR references.', (SELECT id FROM lp2_passage_25)),
  ('listening', 'C1', 'mcq', 'call', 'Why does the speaker set an internal deadline earlier than the legal requirement?', to_jsonb(ARRAY['To impress the supervisory authority with their speed','To allow sufficient time for legal review of the notification','To give the communications team more time to rewrite the template','To ensure the forensic analysis is completed first']::text[]), 'To allow sufficient time for legal review of the notification', 'The speaker says, "I would strongly advise that we aim to have our notification ready by tomorrow evening to allow time for legal review." The earlier internal deadline is explicitly motivated by the need for legal review before the Friday GDPR deadline. Impressing authorities, giving the comms team more time, and completing forensic analysis are not stated as reasons for the earlier deadline.', (SELECT id FROM lp2_passage_25)),
  ('listening', 'C1', 'mcq', 'call', 'What is the current status of the security vulnerability?', to_jsonb(ARRAY['It has not yet been identified','It has been fixed but a broader audit is underway','It is being actively exploited by the attackers','It will be patched within seventy-two hours']::text[]), 'It has been fixed but a broader audit is underway', 'The speaker states, "the vulnerability has been patched, but we are conducting a full audit of all access points." This confirms the specific vulnerability is resolved while a comprehensive review continues. The vulnerability has been identified and fixed, it is not described as being actively exploited, and no seventy-two-hour patching timeline is given.', (SELECT id FROM lp2_passage_25));

-- C1 #3: Partnership Terms (negotiation)
WITH lp2_passage_26 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Negotiating a Distribution Partnership',
      'We appreciate the revised terms, Mr. Petrov, and we can see that your team has made some meaningful concessions. The exclusivity window of eighteen months is something we can work with, provided the performance benchmarks are realistic. That said, I want to be transparent about one area where we are still quite far apart. The proposed revenue share of seventy-thirty in your favour doesn''t adequately reflect the investment we would be making in local marketing and channel development. Our analysis suggests that our go-to-market costs in the first year alone will run to approximately one point two million, and under the current terms, it would take us nearly three years to break even. We''d need to see a sixty-forty split, or alternatively, a lower upfront commitment on the marketing spend. I should also mention that our board has expressed concerns about the liability clause in section twelve. As it stands, it effectively transfers all product liability risk to us as the distributor, which is not standard practice in this industry. We would expect shared liability, at least for the first two years while we are still building market presence. I don''t want these points to overshadow the progress we''ve made. There is clearly a strong strategic fit here, and I believe we can find common ground if both sides show some flexibility on the financials.',
      'listening', 'C1', 'negotiation'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'negotiation', 'What does the speaker imply about the current revenue share proposal?', to_jsonb(ARRAY['It is fair but slightly below their expectations','It would make the partnership financially unviable for them in the short term','It is the only obstacle preventing an agreement','It was better in the previous version of the terms']::text[]), 'It would make the partnership financially unviable for them in the short term', 'The speaker says the seventy-thirty split "doesn''t adequately reflect the investment" they would make and that "it would take us nearly three years to break even" under those terms. This implies short-term financial unviability. The speaker does not call it fair, does not say it is the only obstacle (the liability clause is also raised), and does not compare it to previous terms.', (SELECT id FROM lp2_passage_26)),
  ('listening', 'C1', 'mcq', 'negotiation', 'What is the speaker''s underlying strategy in closing with positive remarks?', to_jsonb(ARRAY['To signal that they are prepared to accept the current terms','To maintain a constructive atmosphere while firmly stating their requirements','To indicate that the financial points are not actually important','To pressure the other side into making immediate concessions']::text[]), 'To maintain a constructive atmosphere while firmly stating their requirements', 'The speaker says, "I don''t want these points to overshadow the progress we''ve made" and emphasizes "a strong strategic fit." This diplomatic closing maintains goodwill while the speaker has just outlined firm requirements on revenue share and liability. The speaker is not accepting current terms, dismissing the financial points, or applying aggressive pressure.', (SELECT id FROM lp2_passage_26)),
  ('listening', 'C1', 'mcq', 'negotiation', 'Why does the speaker mention "standard practice in this industry" regarding the liability clause?', to_jsonb(ARRAY['To suggest that the other party''s proposal is unreasonable by industry standards','To show off their knowledge of distribution agreements','To argue that the clause is illegal under current regulations','To explain why their legal team has not reviewed the contract yet']::text[]), 'To suggest that the other party''s proposal is unreasonable by industry standards', 'By stating that the full transfer of product liability to the distributor "is not standard practice in this industry," the speaker uses industry norms as leverage to argue the clause is unfair. This is a persuasion technique, not a display of knowledge, a legal argument, or an excuse for incomplete review.', (SELECT id FROM lp2_passage_26));

-- C1 #4: Policy Change Communication (email)
WITH lp2_passage_27 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Announcing the New Remote Work Policy',
      'Good morning, everyone. I''m recording this message to accompany the email you''ll receive later today about our updated remote work policy. I know there have been a lot of rumours circulating, so I wanted to address the changes directly and explain the reasoning behind them. Starting from September, we will be moving to a structured hybrid model: three days in the office and two days remote. I want to be upfront that this was not a decision we took lightly. We spent four months analysing productivity data, surveying employees, and consulting with external workplace strategists. The data showed that while individual productivity remained stable during full remote work, cross-functional collaboration and informal knowledge transfer declined noticeably. We also found that newer employees, particularly those who joined during the pandemic, reported feeling disconnected from the company culture. Now, I anticipate that some of you will feel this is a step backward, and I respect that perspective. However, I want to emphasize that this policy includes significant flexibility. Managers will have discretion over which three days their teams come in, and we are introducing a monthly flex day that can be used for personal appointments or focused work. We are also investing in upgrading our office spaces to make them genuinely worth commuting to. I realize actions speak louder than words on that front, but the renovation plans are already underway.',
      'listening', 'C1', 'email'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'email', 'What does the speaker imply by saying "I realize actions speak louder than words on that front"?', to_jsonb(ARRAY['The speaker does not believe the office renovations will happen','The speaker acknowledges that employees may be sceptical about the office upgrade promise until they see results','The speaker is criticizing employees for not trusting management','The speaker is admitting that the policy change is unpopular']::text[]), 'The speaker acknowledges that employees may be sceptical about the office upgrade promise until they see results', 'By using the phrase "actions speak louder than words," the speaker recognizes that simply promising better office spaces may not be convincing and that employees will need to see tangible improvements. The speaker is not expressing personal doubt, criticizing employees, or directly admitting the policy is unpopular, though they do acknowledge some resistance earlier.', (SELECT id FROM lp2_passage_27)),
  ('listening', 'C1', 'mcq', 'email', 'What evidence did the company use to justify the policy change?', to_jsonb(ARRAY['Complaints from senior management about remote work','A decline in cross-functional collaboration and new employee integration','A significant drop in individual employee productivity','Industry benchmarks showing competitors returning to offices']::text[]), 'A decline in cross-functional collaboration and new employee integration', 'The speaker cites two data-driven findings: "cross-functional collaboration and informal knowledge transfer declined noticeably" and "newer employees... reported feeling disconnected from the company culture." Individual productivity is explicitly said to have "remained stable," not declined. Management complaints and competitor benchmarks are not mentioned.', (SELECT id FROM lp2_passage_27)),
  ('listening', 'C1', 'mcq', 'email', 'Why does the speaker record a message rather than relying solely on the email?', to_jsonb(ARRAY['The email contains confidential details that cannot be shared verbally','The speaker wants to address rumours directly and provide personal context for the decision','The email system is unreliable and messages frequently do not arrive','Company policy requires all announcements to be made in video format']::text[]), 'The speaker wants to address rumours directly and provide personal context for the decision', 'The speaker says, "I know there have been a lot of rumours circulating, so I wanted to address the changes directly and explain the reasoning behind them." This suggests the recorded message is meant to combat misinformation with a personal, transparent explanation. Confidentiality, email reliability, and video format requirements are not mentioned.', (SELECT id FROM lp2_passage_27));

-- C1 #5: VIP Client Retention (customer_service)
WITH lp2_passage_28 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Retaining a Key Enterprise Client',
      'Thank you for taking the time to speak with us, Ms. Johansson. I understand that your experience over the past quarter has not met the standards you expect from a premium partner, and I want to assure you that this call is not just about damage control. We genuinely want to understand what went wrong so we can fix it structurally, not just for your account but across our entire service delivery model. You mentioned that the response times on critical tickets have been unacceptable. I''ve reviewed the data, and you''re absolutely right: your average resolution time last quarter was forty-seven hours, which is nearly double our contractual SLA of twenty-four hours. That is not something I can explain away, and I won''t insult your intelligence by trying. What I can tell you is that we have already taken concrete steps. We''ve assigned a dedicated senior engineer to your account, and we''ve restructured our escalation pathway so that any ticket from your team is automatically flagged as priority one. Beyond the technical side, I also want to address the communication gap you raised. Your project manager should have been providing weekly status updates, and the fact that you had to chase us for information is, frankly, embarrassing. Going forward, you will have a direct line to our head of client success, who will personally oversee your account for the next six months. If at the end of that period you don''t see a meaningful improvement, we will waive the early termination fee on your contract.',
      'listening', 'C1', 'customer_service'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'customer_service', 'What does the speaker imply by saying "I won''t insult your intelligence by trying" to explain the poor resolution times?', to_jsonb(ARRAY['The speaker does not know the real reason for the delays','The speaker believes excuses would undermine credibility with a sophisticated client','The speaker thinks the client would not understand the technical reasons','The speaker is blaming a colleague for the problem']::text[]), 'The speaker believes excuses would undermine credibility with a sophisticated client', 'By saying the poor performance "is not something I can explain away" and refusing to "insult your intelligence," the speaker acknowledges that offering excuses to a discerning client would damage trust further. This is a deliberate credibility-building tactic. The speaker is not claiming ignorance, underestimating the client''s understanding, or deflecting blame.', (SELECT id FROM lp2_passage_28)),
  ('listening', 'C1', 'mcq', 'customer_service', 'What is the speaker''s underlying strategy in offering to waive the early termination fee?', to_jsonb(ARRAY['To pressure the client into accepting a longer contract','To demonstrate genuine confidence in their ability to improve, thereby encouraging the client to stay','To comply with a legal requirement in the service agreement','To shift the discussion away from the performance failures']::text[]), 'To demonstrate genuine confidence in their ability to improve, thereby encouraging the client to stay', 'Offering to waive the termination fee after six months signals the speaker''s confidence that the improvements will be sufficient. It also reduces the client''s perceived risk of staying, making retention more likely. The offer does not extend the contract, is not described as a legal requirement, and comes after the speaker has addressed performance failures head-on.', (SELECT id FROM lp2_passage_28)),
  ('listening', 'C1', 'mcq', 'customer_service', 'How far below the contractual standard was the client''s average resolution time?', to_jsonb(ARRAY['It was twelve hours over the SLA','It was nearly double the agreed twenty-four-hour SLA','It was triple the agreed SLA','It exceeded the SLA by exactly forty-seven hours']::text[]), 'It was nearly double the agreed twenty-four-hour SLA', 'The speaker states the average resolution time was "forty-seven hours, which is nearly double our contractual SLA of twenty-four hours." This makes "nearly double" the correct characterization. It is not twelve hours over (that would be thirty-six hours), not triple, and forty-seven hours is the total time, not the amount by which it exceeded the SLA.', (SELECT id FROM lp2_passage_28));

-- C1 #6: Change Management Presentation (general)
WITH lp2_passage_29 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Leading Through Organizational Change',
      'I appreciate the opportunity to share some thoughts on change management, particularly as it relates to the digital transformation initiative we are about to undertake. In my experience, the single biggest reason transformation projects fail is not technology. It is people. More specifically, it is the failure of leadership to bring people along on the journey. We tend to assume that if the business case is compelling enough, people will naturally embrace change. That assumption is dangerously naive. Research from McKinsey suggests that seventy percent of transformation programmes fail to meet their objectives, and the most commonly cited reason is employee resistance and inadequate management support. Now, what does this mean for us practically? It means we need to invest just as heavily in change management as we do in the technology itself. I am proposing that we establish a dedicated change management office, staffed with people who have both the credibility within the organisation and the skills to manage resistance constructively. This is not about spin or internal marketing. It is about honest, ongoing dialogue with every level of the business. People need to understand not just what is changing, but why it is changing and how it will affect them personally. Those who feel they have no voice in the process will find other ways to express their dissatisfaction, and that usually manifests as passive resistance, which is far harder to address than open objection.',
      'listening', 'C1', 'general'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C1', 'mcq', 'general', 'What does the speaker imply by calling the assumption about business cases "dangerously naive"?', to_jsonb(ARRAY['A strong business case is irrelevant to transformation success','Leaders who rely solely on logical arguments risk underestimating the human dimension of change','The speaker believes business cases should not be shared with employees','The phrase is used to criticize a specific colleague''s approach']::text[]), 'Leaders who rely solely on logical arguments risk underestimating the human dimension of change', 'The speaker says "we tend to assume that if the business case is compelling enough, people will naturally embrace change" and calls this "dangerously naive." The implication is that rational arguments alone are insufficient and that ignoring the emotional and personal dimensions of change is a serious leadership mistake. The speaker does not dismiss business cases entirely, withhold information, or target a specific individual.', (SELECT id FROM lp2_passage_29)),
  ('listening', 'C1', 'mcq', 'general', 'According to the speaker, why is passive resistance more problematic than open objection?', to_jsonb(ARRAY['Passive resistance is illegal under employment law','Open objection can be addressed directly, while passive resistance is harder to identify and manage','Passive resistance leads to immediate project cancellation','Open objection usually comes from senior leaders who have more influence']::text[]), 'Open objection can be addressed directly, while passive resistance is harder to identify and manage', 'The speaker says passive resistance "is far harder to address than open objection." The implication is that open disagreement can be engaged with and resolved, whereas passive resistance is subtle, often invisible, and therefore more difficult to counteract. It is not described as illegal, does not necessarily cause cancellation, and is not attributed to any particular level of seniority.', (SELECT id FROM lp2_passage_29)),
  ('listening', 'C1', 'mcq', 'general', 'What specific action does the speaker propose to support the digital transformation?', to_jsonb(ARRAY['Hiring an external consulting firm to manage the entire project','Creating a dedicated change management office with credible internal staff','Delaying the transformation until employee satisfaction improves','Replacing managers who are resistant to the new technology']::text[]), 'Creating a dedicated change management office with credible internal staff', 'The speaker says, "I am proposing that we establish a dedicated change management office, staffed with people who have both the credibility within the organisation and the skills to manage resistance constructively." This is a specific, internally staffed initiative. External consultants, project delays, and replacing managers are not proposed.', (SELECT id FROM lp2_passage_29));

-- ============================================================
-- C2 PASSAGES (lp2_passage_30 through lp2_passage_35)
-- ============================================================

-- C2 #1: Ethical Sourcing Decision (meeting)
WITH lp2_passage_30 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'The Ethical Sourcing Dilemma',
      'I think we need to have a very frank conversation about the audit findings from our Tier 2 suppliers in Bangladesh. The report, which I trust everyone has read, paints a picture that is, to put it diplomatically, deeply troubling. Two of the five facilities inspected showed clear evidence of excessive overtime hours, well beyond what our code of conduct permits, and one facility had inadequate fire safety provisions. Now, the easy thing to do would be to terminate those contracts immediately. It would make for a clean press release and satisfy our ESG reporting obligations. But I want to push back on that instinct for a moment. If we pull out, approximately three thousand workers lose their livelihoods overnight, and the factories will simply find another buyer with lower standards. We will have washed our hands of the problem without actually solving it. The harder path, and I would argue the more ethical one, is to stay engaged, invest in remediation, and hold those suppliers to a clear improvement timeline with genuine consequences for non-compliance. I am not suggesting we turn a blind eye. Quite the opposite. I am proposing that we deploy our own compliance officers on-site for the next twelve months and tie continued business to measurable progress on a quarterly basis. The reputational risk of staying is real, I grant you that. If this leaks before we can show tangible improvements, the narrative writes itself. But the reputational risk of a hollow exit that displaces thousands of workers is arguably worse in the long run, especially given the scrutiny that ethical consumerism attracts nowadays. I would also point out that our competitor, Vanguard Apparel, took the remediation approach two years ago in a similar situation, and it has since become a cornerstone of their brand story. We have a chance to do something meaningful here, but only if we are prepared to commit the resources and accept the short-term discomfort.',
      'listening', 'C2', 'meeting'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'meeting', 'What is the speaker''s attitude toward the option of immediately terminating the supplier contracts?', to_jsonb(ARRAY['Fully supportive, as it protects the company''s reputation','Dismissive, viewing it as a superficially satisfying but ultimately irresponsible response','Neutral, presenting it as equally valid to the remediation approach','Supportive in principle but concerned about the legal implications']::text[]), 'Dismissive, viewing it as a superficially satisfying but ultimately irresponsible response', 'The speaker calls immediate termination "the easy thing" that "would make for a clean press release" but argues it means "we will have washed our hands of the problem without actually solving it." The phrase "washed our hands" carries a moral judgment, implying the exit would be an abdication of responsibility. The speaker clearly favours remediation and does not treat the options as equally valid or express concern about legal issues.', (SELECT id FROM lp2_passage_30)),
  ('listening', 'C2', 'mcq', 'meeting', 'What unstated assumption underlies the speaker''s argument about reputational risk?', to_jsonb(ARRAY['The media will never discover the audit findings','Consumers and stakeholders increasingly evaluate companies on the substance of their ethical actions, not just the optics','The company''s shareholders do not care about ethical sourcing','Vanguard Apparel''s approach failed and the speaker wants to avoid repeating their mistake']::text[]), 'Consumers and stakeholders increasingly evaluate companies on the substance of their ethical actions, not just the optics', 'The speaker argues that a "hollow exit" carries worse long-term reputational risk than staying, "especially given the scrutiny that ethical consumerism attracts nowadays." The unstated assumption is that informed consumers and stakeholders can distinguish between genuine ethical commitment and performative gestures. The speaker clearly expects media scrutiny (not absence of it), assumes shareholders care, and cites Vanguard Apparel as a positive example, not a failure.', (SELECT id FROM lp2_passage_30)),
  ('listening', 'C2', 'mcq', 'meeting', 'Why does the speaker mention Vanguard Apparel''s experience?', to_jsonb(ARRAY['To argue that competitors are overtaking them in all areas','To provide a precedent showing that the remediation approach can ultimately strengthen a brand','To suggest that they should acquire Vanguard Apparel','To criticize Vanguard Apparel''s ethical record']::text[]), 'To provide a precedent showing that the remediation approach can ultimately strengthen a brand', 'The speaker says Vanguard Apparel "took the remediation approach two years ago in a similar situation, and it has since become a cornerstone of their brand story." This is used as evidence that staying engaged and investing in improvement can yield positive brand outcomes. The speaker is not criticizing Vanguard, suggesting acquisition, or making a broad competitive comparison.', (SELECT id FROM lp2_passage_30));

-- C2 #2: Stakeholder Management with Competing Interests (call)
WITH lp2_passage_31 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Balancing Investor and Community Interests',
      'I appreciate you both joining this call, and I want to be straightforward about why I''ve brought you together. We are facing a situation where our obligations to our investors and our commitments to the local community in Grafton are pulling us in opposite directions, and I don''t think we can resolve it without putting everything on the table. Richard, your fund holds a twelve percent stake, and you have made it clear that the Grafton manufacturing plant needs to deliver a return on investment within eighteen months or the board should consider closure. I hear you, and from a pure numbers perspective, your position is defensible. However, Miranda, as our community liaison, you have been telling us for months that closing Grafton would devastate a town where we are the largest employer. Six hundred jobs, a sponsorship of the local training college, and twenty years of community investment do not simply evaporate without consequences. Here is what I think neither side has fully reckoned with. Richard, if we close Grafton and it becomes a media story about corporate abandonment, the reputational damage could affect our share price more than the plant''s operating losses ever will. And Miranda, I have to be honest: keeping the plant open as a form of corporate charity is not sustainable, and eventually the numbers will force the same outcome anyway, just later and with more pain. What I am proposing is a third path. We invest in retooling Grafton for our electric vehicle component line, which gives the plant a viable commercial future, preserves the majority of the jobs, and gives Richard''s fund a credible growth narrative for their stakeholders. It will require upfront capital, and the payback period extends to about thirty months, but I believe it is the only option that does not end badly for someone at this table.',
      'listening', 'C2', 'call'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'call', 'What is the speaker''s implicit criticism of both Richard''s and Miranda''s positions?', to_jsonb(ARRAY['Both are acting in bad faith and should be removed from the discussion','Both are focused on short-term considerations and have not fully examined the long-term consequences of their preferred outcomes','Both are too emotional to make rational business decisions','Both have conflicts of interest that disqualify them from the discussion']::text[]), 'Both are focused on short-term considerations and have not fully examined the long-term consequences of their preferred outcomes', 'The speaker tells Richard that closure could damage the share price more than operating losses, and tells Miranda that keeping the plant open as "corporate charity is not sustainable" and "eventually the numbers will force the same outcome anyway." The phrase "neither side has fully reckoned with" implies both have blind spots regarding consequences. The speaker does not accuse either of bad faith, excessive emotion, or disqualifying conflicts of interest.', (SELECT id FROM lp2_passage_31)),
  ('listening', 'C2', 'mcq', 'call', 'What rhetorical technique does the speaker use to present the retooling proposal?', to_jsonb(ARRAY['Appealing to emotion by describing the suffering of Grafton''s workers','Framing it as the only rational alternative after systematically dismantling both existing positions','Threatening both parties with legal consequences if they refuse','Using technical jargon to confuse the participants into agreement']::text[]), 'Framing it as the only rational alternative after systematically dismantling both existing positions', 'The speaker methodically addresses the flaws in both Richard''s closure argument and Miranda''s preservation argument before presenting the retooling proposal as "the only option that does not end badly for someone at this table." This is a classic deliberative technique: eliminate alternatives, then present the remaining option as the logical conclusion. The speaker uses some emotional context but relies primarily on logical argument, not threats or obfuscation.', (SELECT id FROM lp2_passage_31)),
  ('listening', 'C2', 'mcq', 'call', 'What does the speaker mean by saying the retooling gives Richard''s fund "a credible growth narrative for their stakeholders"?', to_jsonb(ARRAY['The fund can use the Grafton story to attract new investors by demonstrating commitment to sustainable growth','The fund will need to lie to its stakeholders about the plant''s performance','The speaker is offering Richard a personal financial incentive','The fund''s stakeholders have demanded investment in electric vehicles']::text[]), 'The fund can use the Grafton story to attract new investors by demonstrating commitment to sustainable growth', 'By saying the retooling provides "a credible growth narrative," the speaker implies that the fund can present the electric vehicle component pivot as a forward-looking investment to its own investors, making it commercially attractive beyond just Grafton''s survival. The speaker is not suggesting dishonesty, personal incentives, or specific stakeholder demands.', (SELECT id FROM lp2_passage_31));

-- C2 #3: Complex IP Licensing (negotiation)
WITH lp2_passage_32 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Navigating the Licensing Impasse',
      'I want to acknowledge that we have reached something of an impasse, and I think it is worth stepping back to understand why. On the surface, this is a licensing negotiation over three patent families. But what is really happening, and I suspect both sides feel this even if we have not said it aloud, is a negotiation about the future balance of power in this market segment. Your patents give you a defensive moat, and our manufacturing scale gives us distribution reach you cannot easily replicate. Neither of us can afford to walk away, and neither of us wants to set a precedent that weakens our position in future deals. So let me try a different framing. Instead of haggling over per-unit royalty rates, which is where we have been stuck for three sessions now, what if we structure this as a cross-licensing arrangement with a technology exchange component? You license us the three patent families at a rate of one point eight percent, which is below your ask but above our counteroffer. In return, we grant you access to our proprietary coating technology, which your R and D team has been trying to develop independently for, if our intelligence is correct, about eighteen months now. I realize that bringing your internal R and D efforts into the conversation might feel like an overstep, but I raise it because it illustrates a broader point: we are both spending resources trying to replicate what the other already has. A cross-licensing deal stops that duplication and lets both companies redirect those resources toward actual innovation. The per-unit economics become almost secondary when you factor in the R and D savings. I am not pretending this is a perfectly balanced offer. It is not. But it is a starting point that moves us off the positional bargaining that has been going nowhere.',
      'listening', 'C2', 'negotiation'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'negotiation', 'What does the speaker suggest is the real underlying issue in the negotiation?', to_jsonb(ARRAY['A personal conflict between the lead negotiators on both sides','A dispute over which company invented the technology first','A struggle over long-term competitive positioning in the market, not just the immediate licensing terms','Uncertainty about whether the patents are legally valid']::text[]), 'A struggle over long-term competitive positioning in the market, not just the immediate licensing terms', 'The speaker says, "what is really happening... is a negotiation about the future balance of power in this market segment" and notes that neither side "wants to set a precedent that weakens our position in future deals." This frames the real issue as strategic positioning beyond the immediate deal. Personal conflicts, invention disputes, and patent validity are not mentioned.', (SELECT id FROM lp2_passage_32)),
  ('listening', 'C2', 'mcq', 'negotiation', 'Why does the speaker reference the other company''s internal R and D efforts, and what does this reveal about their negotiation approach?', to_jsonb(ARRAY['To embarrass the other side and force a quick concession','To demonstrate superior intelligence gathering and subtly signal leverage while reframing the negotiation around mutual benefit','To prove that the other company''s patents are based on stolen technology','To suggest that the other company''s R and D team is incompetent']::text[]), 'To demonstrate superior intelligence gathering and subtly signal leverage while reframing the negotiation around mutual benefit', 'The speaker acknowledges that "bringing your internal R and D efforts into the conversation might feel like an overstep" but uses it to illustrate that "we are both spending resources trying to replicate what the other already has." This serves a dual purpose: it signals the speaker''s information advantage (a subtle power move) while simultaneously reframing the discussion toward efficiency and mutual gain. The speaker is not trying to embarrass, accuse of theft, or insult competence.', (SELECT id FROM lp2_passage_32)),
  ('listening', 'C2', 'mcq', 'negotiation', 'What does the speaker mean by saying "I am not pretending this is a perfectly balanced offer"?', to_jsonb(ARRAY['The speaker is admitting the deal is unfair and should be rejected','The speaker is using strategic candour to build trust by acknowledging the offer''s imperfections while positioning it as a pragmatic step forward','The speaker is warning that the other side will need to make all the concessions','The speaker does not actually understand the financial details of the proposal']::text[]), 'The speaker is using strategic candour to build trust by acknowledging the offer''s imperfections while positioning it as a pragmatic step forward', 'By openly admitting the offer is imperfect, the speaker demonstrates honesty and avoids the credibility loss that comes from overselling. The follow-up phrase "but it is a starting point that moves us off the positional bargaining that has been going nowhere" repositions the imperfect offer as progress rather than a final demand. This is strategic candour, not a concession of unfairness, a demand for one-sided concessions, or a sign of ignorance.', (SELECT id FROM lp2_passage_32));

-- C2 #4: Enterprise Dispute Resolution (customer_service)
WITH lp2_passage_33 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'Resolving a Multi-Million Dollar Service Failure',
      'Dr. Hartmann, I want to begin by saying that what happened with your implementation is not simply a service failure. It is a systemic breakdown that exposed weaknesses we should have identified long before your project went live. I have read the incident report in its entirety, and I will not hide behind the usual caveats about root cause analysis still being underway. The facts are clear enough. Your team was promised a seamless migration of fourteen years of clinical trial data, and what you received was a system that corrupted timestamp metadata on approximately twelve percent of your records. For a pharmaceutical company operating under FDA audit requirements, that is not an inconvenience. It is an existential risk to your regulatory standing. I understand that your legal counsel has already drafted a formal claim, and frankly, I would have been surprised if they had not. But before we move into adversarial territory, I want to propose something that I believe serves both our interests more effectively than litigation. We are prepared to deploy a dedicated forensic data team, at our expense, to reconstruct every affected record using your archived source files and our backup snapshots. Our preliminary assessment suggests this is achievable within six to eight weeks. Concurrently, we will provide your compliance team with a detailed audit trail documenting every correction, which you can submit to the FDA as evidence of data integrity. Additionally, we are offering to waive your service fees for the remainder of the contract year and extend your licence at the current rate for an additional three years. I recognize that no amount of remediation fully undoes the disruption you have experienced. But I would submit that this path gets you back to a defensible regulatory position far more quickly than a legal process that could stretch over eighteen months while the data issues remain unresolved.',
      'listening', 'C2', 'customer_service'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'customer_service', 'What is the speaker''s implicit argument against pursuing litigation?', to_jsonb(ARRAY['Litigation would be too expensive for Dr. Hartmann''s company to pursue','The legal claim has no merit and would be dismissed','Litigation would leave the underlying data problem unresolved for an extended period, worsening the regulatory risk','The speaker is threatening to countersue if litigation proceeds']::text[]), 'Litigation would leave the underlying data problem unresolved for an extended period, worsening the regulatory risk', 'The speaker says the proposed path "gets you back to a defensible regulatory position far more quickly than a legal process that could stretch over eighteen months while the data issues remain unresolved." The implicit argument is that litigation addresses the financial dimension but leaves the urgent data and regulatory problems untouched for a dangerously long time. The speaker does not question the claim''s merit, reference the client''s finances, or threaten a countersuit.', (SELECT id FROM lp2_passage_33)),
  ('listening', 'C2', 'mcq', 'customer_service', 'What does the speaker''s phrase "I will not hide behind the usual caveats" reveal about their communication strategy?', to_jsonb(ARRAY['The speaker is criticizing their own legal team for advising caution','The speaker is deliberately abandoning the typical corporate defensiveness to establish credibility and trust with the client','The speaker does not believe a root cause analysis is necessary','The speaker is admitting legal liability on behalf of the company']::text[]), 'The speaker is deliberately abandoning the typical corporate defensiveness to establish credibility and trust with the client', 'By explicitly rejecting the standard corporate response of deferring to ongoing investigations, the speaker signals transparency and accountability. The phrase "the facts are clear enough" reinforces this by acknowledging what is already known rather than stalling. This builds trust with a sophisticated client. The speaker is not criticizing their legal team, dismissing the need for analysis, or making a formal legal admission.', (SELECT id FROM lp2_passage_33)),
  ('listening', 'C2', 'mcq', 'customer_service', 'Why does the speaker describe the data corruption as "an existential risk to your regulatory standing" rather than simply a technical error?', to_jsonb(ARRAY['To exaggerate the problem and increase the client''s sense of dependency','To demonstrate understanding of the client''s industry-specific stakes and signal that the proposed remedy addresses the real threat, not just the surface problem','To frighten the client into accepting the first offer without negotiating','To shift blame to the FDA for imposing unreasonable requirements']::text[]), 'To demonstrate understanding of the client''s industry-specific stakes and signal that the proposed remedy addresses the real threat, not just the surface problem', 'By framing the issue in terms of FDA compliance and regulatory standing rather than mere technical malfunction, the speaker shows awareness of the pharmaceutical industry context. This validates the client''s concerns and positions the proposed remediation (including the audit trail for the FDA) as directly addressing the highest-stakes dimension of the problem. The speaker is not exaggerating, pressuring, or blaming the FDA.', (SELECT id FROM lp2_passage_33));

-- C2 #5: Executive Succession and Culture (general)
WITH lp2_passage_34 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'The Succession Question',
      'I know the succession question makes some of you uncomfortable, and that discomfort is precisely why we need to discuss it now rather than when it becomes urgent. Margaret has led this company for seventeen years, and the culture, for better and for worse, is deeply intertwined with her personal leadership style. That is not a criticism. It is an observation about organisational reality. When a founder-led company transitions to its next leader, the risk is not that things will change. Of course they will. The risk is that we have not articulated which elements of our culture are genuinely load-bearing and which are simply habits that formed around one person''s preferences. Let me give you a concrete example. Our flat hierarchy is something we all point to with pride. But is it truly flat, or have we simply replaced formal structure with informal influence networks that radiate out from Margaret? If it is the latter, then a new CEO who lacks her specific relationships will inherit the title but not the actual levers of power, and we will end up with a leadership vacuum disguised as a smooth transition. I am not advocating for bureaucracy. I am arguing that we need to formalise the decision-making pathways that currently exist only in people''s heads before Margaret steps back, not after. There is also the question of what kind of leader we actually need next. The temptation will be to find someone who resembles Margaret as closely as possible, a kind of continuity hire. But the market we operate in today is fundamentally different from the one she built this company in. We may need a leader whose strengths complement what Margaret built rather than replicate it, and that is a much harder conversation to have while she is still in the room.',
      'listening', 'C2', 'general'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'general', 'What does the speaker imply by the phrase "a leadership vacuum disguised as a smooth transition"?', to_jsonb(ARRAY['The new CEO will deliberately sabotage the company from within','The company may appear stable on the surface while the new leader lacks the informal authority needed to actually govern','Margaret is planning to continue controlling the company after stepping down','The board is intentionally appointing a weak successor to maintain their own power']::text[]), 'The company may appear stable on the surface while the new leader lacks the informal authority needed to actually govern', 'The speaker argues that if the flat hierarchy actually relies on "informal influence networks that radiate out from Margaret," then a successor "will inherit the title but not the actual levers of power." A "leadership vacuum disguised as a smooth transition" means the change looks orderly externally while the new leader is effectively powerless. There is no suggestion of sabotage, Margaret''s continued control, or board manipulation.', (SELECT id FROM lp2_passage_34)),
  ('listening', 'C2', 'mcq', 'general', 'What is the speaker''s unstated conclusion about Margaret''s potential involvement in selecting her successor?', to_jsonb(ARRAY['Margaret should have sole authority over the selection','Margaret''s presence in the discussion may bias the board toward a continuity hire rather than the leader the company actually needs','Margaret should be excluded from all future board meetings','Margaret''s opinion is irrelevant because she is retiring']::text[]), 'Margaret''s presence in the discussion may bias the board toward a continuity hire rather than the leader the company actually needs', 'The speaker says the conversation about a different kind of leader "is a much harder conversation to have while she is still in the room," implying that Margaret''s presence may unconsciously steer the board toward replicating her style rather than choosing the complementary leader the speaker believes is needed. This is a diplomatic suggestion about influence dynamics, not a call for exclusion or dismissal of her opinion.', (SELECT id FROM lp2_passage_34)),
  ('listening', 'C2', 'mcq', 'general', 'What distinction does the speaker draw between "load-bearing" cultural elements and "habits"?', to_jsonb(ARRAY['Load-bearing elements are profitable while habits are costly','Load-bearing elements are essential to the organisation''s functioning, while habits are incidental patterns shaped by individual leadership style','Load-bearing elements are written policies while habits are unwritten rules','There is no real difference; the speaker uses both terms interchangeably']::text[]), 'Load-bearing elements are essential to the organisation''s functioning, while habits are incidental patterns shaped by individual leadership style', 'The speaker asks which cultural elements "are genuinely load-bearing and which are simply habits that formed around one person''s preferences." The architectural metaphor of "load-bearing" implies structural necessity: elements the organisation cannot function without. "Habits" are patterns that exist because of Margaret''s personal style, not because they are essential. The distinction is not about profitability, written versus unwritten rules, or interchangeable terminology.', (SELECT id FROM lp2_passage_34));

-- C2 #6: Regulatory Compliance Under Pressure (email)
WITH lp2_passage_35 AS (
  INSERT INTO public.passages (title, body, skill, cefr_level, context_tag)
    VALUES (
      'The Compliance Tightrope',
      'I am leaving this message for the record, and I want to be very precise in my language because I suspect this conversation may be revisited at some point. The situation we are in is this: our European operations have flagged that the new emissions reporting framework requires us to include Scope 3 data in our annual disclosure, effective January. The problem is that our supply chain tracking systems are not capable of producing Scope 3 data at the level of granularity the regulation demands. We have two options, and I want to be transparent about the trade-offs of each. Option one is to submit the disclosure with estimated Scope 3 data based on industry averages and accepted modelling methodologies. This is technically compliant in the sense that the regulation allows for estimation where primary data is unavailable, provided you disclose your methodology and its limitations. However, and this is where it gets uncomfortable, our competitors who have invested in supply chain traceability will be submitting actual measured data, which will make our estimates look evasive by comparison even if they are perfectly legal. Option two is to request a formal extension from the regulatory body, citing system limitations. This is transparent, but it signals to the market that we are behind our peers on ESG infrastructure, which has implications for our sustainability-linked bond covenants. Both options carry risk, and I want to be clear that I am not comfortable with a third path that has been informally suggested, which is to present modelled data without adequate disclosure of its estimated nature. That would cross a line from pragmatic compliance into misrepresentation, and regardless of the short-term convenience, it is not something I am prepared to endorse. I would like the executive committee to make a formal decision on this by the end of the week so that we have adequate time to prepare whichever submission we choose.',
      'listening', 'C2', 'email'
    )
  RETURNING id
)
INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation, passage_id) VALUES
  ('listening', 'C2', 'mcq', 'email', 'Why does the speaker begin by saying "I want to be very precise in my language because I suspect this conversation may be revisited"?', to_jsonb(ARRAY['The speaker is concerned about being quoted out of context and is creating a deliberate record of their position, particularly their objection to the undisclosed approach','The speaker is preparing a legal case against the company','The speaker is rehearsing for a public presentation','The speaker wants to impress colleagues with their communication skills']::text[]), 'The speaker is concerned about being quoted out of context and is creating a deliberate record of their position, particularly their objection to the undisclosed approach', 'By stating the message is "for the record" and emphasising precision, the speaker is establishing a documented position in case the matter is later investigated or disputed. This is especially significant given the speaker''s subsequent rejection of the informally suggested third path. The speaker is protecting themselves professionally, not preparing litigation, rehearsing, or seeking to impress.', (SELECT id FROM lp2_passage_35)),
  ('listening', 'C2', 'mcq', 'email', 'What is the speaker''s attitude toward the "third path" that has been informally suggested?', to_jsonb(ARRAY['Cautiously supportive, provided the methodology is disclosed','Firmly opposed, viewing it as crossing an ethical boundary from acceptable pragmatism into misrepresentation','Indifferent, leaving the decision entirely to the executive committee','Interested but wanting more information before forming an opinion']::text[]), 'Firmly opposed, viewing it as crossing an ethical boundary from acceptable pragmatism into misrepresentation', 'The speaker says the third path "would cross a line from pragmatic compliance into misrepresentation" and states it "is not something I am prepared to endorse." The language is unambiguous: the speaker draws a clear ethical boundary. They are not cautiously supportive, indifferent, or undecided. The use of "cross a line" and "not prepared to endorse" signals firm principled opposition.', (SELECT id FROM lp2_passage_35)),
  ('listening', 'C2', 'mcq', 'email', 'What dilemma does the speaker identify with Option one, and what does it reveal about the competitive landscape?', to_jsonb(ARRAY['Option one is illegal and the speaker knows the company will be fined','Option one is technically compliant but will appear evasive compared to competitors who can submit actual data, revealing that the company has underinvested in supply chain traceability','Option one requires sharing proprietary supply chain data with competitors','Option one would satisfy regulators but anger the company''s own shareholders']::text[]), 'Option one is technically compliant but will appear evasive compared to competitors who can submit actual data, revealing that the company has underinvested in supply chain traceability', 'The speaker explains that estimated data is "technically compliant" but that competitors "who have invested in supply chain traceability will be submitting actual measured data, which will make our estimates look evasive by comparison." This reveals a competitive gap in ESG infrastructure investment. Option one is not illegal, does not require sharing data with competitors, and the speaker frames the risk as market perception rather than shareholder anger specifically.', (SELECT id FROM lp2_passage_35));
